// 错误示例：在协程中使用 synchronized
class Counter {
    private var count = 0
    suspend fun increment() {
        synchronized(this) { // 问题：阻塞了协程所在的线程
            count++
        }
    }
}

// 正确示例：使用 Mutex
class SafeCounter {
    private var count = 0
    private val mutex = Mutex()
    suspend fun increment() {
        mutex.withLock {
            count++
        }
    }
}
